    ok(tabs==['Inicio','Operación','Nuevo','Admin.','Ajustes'] and pg.locator('.tabbar [data-tab="admin"]').get_attribute('aria-label')=='Administración','barra principal: '+' | '.join(tabs))
    ics=pg.locator('.div-ic svg.ic').count()
    ok(ics==2 and pg.locator('.div-ic img').count()==0,'Inicio usa íconos de línea para Puerto y Campo (sin ilustraciones rasterizadas)')
    shot(pg,'n01_inicio')
    pg.locator('.tabbar [data-tab="admin"]').click(); pg.wait_for_timeout(600)
    cards=[x.inner_text().split('\n')[0] for x in pg.locator('.mod-card').all()]; ok(cards==['Operadores','Unidades','Cobranza','Tarifas','Documentos','Catálogos'],'Administración: '+', '.join(cards)); shot(pg,'n02_admin')
    pg.locator('.tabbar [data-tab="settings"]').click(); pg.wait_for_timeout(600)
    ok('Catálogos' not in pg.locator('.page').inner_text() and 'Administrar catálogos' not in pg.locator('.page').inner_text(),'Ajustes ya no contiene Catálogos')
    pg.locator('.tabbar .tab-new').click(); pg.wait_for_timeout(400)
    nopts=[x.inner_text().split('\n')[0] for x in pg.locator('.new-opt').all()]; ok(nopts==['Nota de entrega','Asignación de unidades','Viaje de operador','Recarga de combustible'],'Nuevo: '+', '.join(nopts)); shot(pg,'n03_nuevo'); pg.keyboard.press('Escape')
    # ===== Remolques: tipo y filtros =====
    pg.goto(BASE+'#/catalogos/trailers'); pg.wait_for_timeout(700)
