    rows=[x.inner_text().split('\n')[0] for x in pg.locator('.list .row .unit-badge').all()]; ok(rows==['U21','U08'],'comparar: mejor rendimiento primero '+str(rows))
    pg.locator('[data-sort="amount"]').click(); pg.wait_for_timeout(200); rows=[x.inner_text() for x in pg.locator('.list .row .unit-badge').all()]; ok(rows[0]=='U08','ordenar por mayor gasto: U08 ($14,022) antes que U21 ($13,940)')
    ok('Unidades activas\n2' in pg.locator('.tiles').first.inner_text(),'resumen de flota del mes'); shot(pg,'n17_flota')
    pg.locator('[data-per="mesAnt"]').click(); pg.wait_for_timeout(200); ok('No hay recargas en este periodo' in pg.locator('.page').inner_text(),'filtro de periodo (mes anterior sin recargas)')
