    pg.locator('[data-per="mes"]').click(); pg.locator('[data-export]').click(); pg.wait_for_selector('[data-xgo]'); pg.locator('[data-xgo]').click(); pg.wait_for_selector('[data-xs]',timeout=10000); shot(pg,'n18_excel')
