    ok(sum(1 for r in R.iter_rows(min_row=7) if r[2].value in ('U21','U08'))==6,'Excel: 6 recargas del mes')
    bk=pg.evaluate('''async()=>{const m=await import('/src/services/backup.js');const f=await m.exportBackup({includeMedia:false});const o=JSON.parse(await f.text());return {fuel:o.data.fuelRecords.length,avatar:o.data.attachments.filter(a=>a.kind==='avatar').length,types:o.data.trailers.filter(t=>t.type).length,rfc:o.data.operators.filter(x=>x.rfc).length}}''')
    ok(bk=={'fuel':7,'avatar':1,'types':4,'rfc':1},'respaldo incluye recargas, foto del operador, tipos de remolque y RFC: '+str(bk))
    pg.emulate_media(color_scheme='dark'); pg.goto(BASE+'#/'); pg.wait_for_timeout(700); shot(pg,'n19_oscuro_inicio'); pg.goto(BASE+'#/operacion/combustible/'+pg.evaluate("(async()=>{const m=await import('/src/services/fuel.js');return m.vehicles().find(v=>v.label==='U21').id})()")); pg.wait_for_timeout(900); shot(pg,'n20_oscuro_unidad')
